import numpy as np

N = 3
C = np.zeros((N, N), dtype=int)

# Construction: C[i, j] = i + j + 1 (1-indexed coordinates i, j)
# Colors range from 1+1+1=3 to 3+3+1=7. Total 5 distinct colors.
# Wait, using i+j directly for 1-indexed, colors range from 2 to 6. Total 5 distinct colors.
# Let's use C[i, j] = i + j.
for i in range(N):
    for j in range(N):
        C[i, j] = (i + 1) + (j + 1)

print("Generated 3x3 Matrix C:")
print(C)

# Verification function
def check_constraint(matrix):
    N_mat = matrix.shape[0]
    for i in range(N_mat - 1):
        for j in range(N_mat - 1):
            subgrid = [
                matrix[i, j], matrix[i, j+1],
                matrix[i+1, j], matrix[i+1, j+1]
            ]
            # Count distinct colors
            distinct_colors = len(set(subgrid))
            if distinct_colors == 4:
                return False
    return True

if check_constraint(C):
    print("\nConstraint satisfied.")
else:
    print("\nConstraint failed.")
